/**
 * Build functions/.env.<projectId> from the repo root .env for Firebase deploy.
 * Gitignored output — never commit the generated file.
 */
const fs = require("fs");
const path = require("path");
require("dotenv").config({ path: path.join(__dirname, "..", ".env") });

const PROJECT_ID = "newsa-ea4dc";
const outPath = path.join(__dirname, "..", "functions", `.env.${PROJECT_ID}`);

function readJsonFromPath(envPath) {
  if (!envPath?.trim()) return null;
  const keyPath = path.isAbsolute(envPath) ? envPath : path.resolve(process.cwd(), envPath);
  return fs.readFileSync(keyPath, "utf8").trim();
}

function quoteEnv(value) {
  if (value == null || value === "") return "";
  const s = String(value);
  if (/[\s#"']/.test(s)) return JSON.stringify(s);
  return s;
}

const passthroughKeys = [
  "APP_BASE_URL",
  "SUPABASE_URL",
  "SUPABASE_SERVICE_ROLE_KEY",
  "AIRTABLE_API_KEY",
  "AIRTABLE_BASE_ID",
  "AIRTABLE_TABLE_ID",
  "AIRTABLE_CAPITAL_TABLE_ID",
  "AIRTABLE_ATFX_TOPIC_PROMPT_FIELD",
  "FMP_API_KEY",
  "CHART_IMG_API_KEY",
  "REQUESTY_API_KEY",
  "TELEGRAM_BOT_TOKEN",
  "SMTP_HOST",
  "SMTP_PORT",
  "SMTP_SECURE",
  "SMTP_USER",
  "SMTP_PASS",
  "SMTP_FROM",
  "N8N_APPROVE_WEBHOOK_URL",
  "N8N_APPROVE_WEBHOOK_USER",
  "N8N_APPROVE_WEBHOOK_PASSWORD",
  "N8N_TWITT_POST_WEBHOOK_URL",
  "N8N_TWITT_POST_WEBHOOK_USER",
  "N8N_TWITT_POST_WEBHOOK_PASSWORD",
  "N8N_ONEUPTICK_PUBLISH_WEBHOOK_URL",
  "N8N_ONEUPTICK_PUBLISH_WEBHOOK_USER",
  "N8N_ONEUPTICK_PUBLISH_WEBHOOK_PASSWORD",
  "N8N_ONEUPTICK_SEO_PUBLISH_WEBHOOK_URL",
  "ATFX_WORDPRESS_SITE_URL",
  "ATFX_WORDPRESS_USERNAME",
  "ATFX_WORDPRESS_APP_PASSWORD",
  "ATFX_WORDPRESS_POST_STATUS",
];

const lines = [
  `# Generated by scripts/sync-functions-env.cjs — do not commit.`,
  `# Firebase project: ${PROJECT_ID}`,
  "",
];

for (const key of passthroughKeys) {
  const value = process.env[key];
  if (value != null && String(value).trim() !== "") {
    lines.push(`${key}=${quoteEnv(value)}`);
  }
}

try {
  const firebaseSa = readJsonFromPath(process.env.FIREBASE_SERVICE_ACCOUNT);
  if (firebaseSa) lines.push(`GOOGLE_SERVICE_ACCOUNT=${JSON.stringify(firebaseSa)}`);
} catch (e) {
  console.warn("Could not read FIREBASE_SERVICE_ACCOUNT:", e.message);
}

try {
  const oneuptickSa = readJsonFromPath(process.env.ONEUPTICK_FIREBASE_SERVICE_ACCOUNT_PATH);
  if (oneuptickSa) lines.push(`ONEUPTICK_FIREBASE_SERVICE_ACCOUNT=${JSON.stringify(oneuptickSa)}`);
} catch (e) {
  console.warn("Could not read ONEUPTICK_FIREBASE_SERVICE_ACCOUNT_PATH:", e.message);
}

fs.writeFileSync(outPath, lines.join("\n") + "\n");
console.log(`Wrote ${outPath} (${lines.length} lines)`);
